import {getProfile,defaultAvatar} from './profile-store.js?v=30';
const svg=(paths)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
const icons={user:svg('<circle cx="12" cy="8" r="3.5"/><path d="M4.5 21v-2a7.5 7.5 0 0 1 15 0v2"/>'),menu:svg('<path d="M4 6h16M4 12h16M4 18h16"/>'),home:svg('<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8"/>'),works:svg('<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m4 16 5-5 4 4 3-3 4 4"/><circle cx="15" cy="8" r="1"/>'),orders:svg('<path d="M7 5h10l3 4v12H4V9zM7 5V3h10v2M4 9h16M9 13h6"/>'),about:svg('<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>'),contact:svg('<path d="M5 18 3 21v-6a9 9 0 1 1 4 5"/><path d="M8 11h.01M12 11h.01M16 11h.01"/>'),close:svg('<path d="m6 6 12 12M18 6 6 18"/>')};
const header=document.querySelector('.flow-header,.header');
if(header){
 const en=()=>document.documentElement.lang.startsWith('en');
 const t=(zh,eng)=>en()?eng:zh;
 const actions=document.createElement('div');actions.className='mn-actions';actions.innerHTML=`<a href="./account.html" aria-label="个人中心" data-mobile-label data-mn-zh="个人中心" data-mn-en="My account">${icons.user}</a><button class="mn-open" aria-label="打开菜单" aria-expanded="false" aria-controls="mn-drawer" data-mobile-label data-mn-zh="打开菜单" data-mn-en="Open menu">${icons.menu}</button>`;header.append(actions);const desktopAccount=document.createElement('a');desktopAccount.className='pc-account';desktopAccount.href='./account.html';const desktopContainer=header.querySelector('.nav-right')||[...header.children].find(el=>el.tagName==='DIV'&&el!==actions);if(desktopContainer)desktopContainer.append(desktopAccount);
 function syncAvatar(){const profile=getProfile();for(const link of [actions.querySelector('a'),desktopAccount]){link.replaceChildren();link.setAttribute('aria-label',t('个人中心','My account'));if(profile){const img=document.createElement('img');img.src=profile.avatar||defaultAvatar;img.alt='';link.append(img);link.classList.add('is-signed-in');}else{link.innerHTML=icons.user;link.classList.remove('is-signed-in');}}}window.addEventListener('popomo-profile-change',syncAvatar);window.addEventListener('storage',syncAvatar);syncAvatar();
 const drawer=document.createElement('div');drawer.hidden=true;drawer.setAttribute('role','dialog');drawer.setAttribute('aria-modal','true');drawer.id='mn-drawer';drawer.className='mn-drawer';drawer.setAttribute('aria-label','主菜单');
 drawer.innerHTML=`<header class="mn-drawer-head"><a href="./" class="mn-wordmark">POPOMO<sup>®</sup></a><button class="mn-close" aria-label="关闭菜单" data-mobile-label data-mn-zh="关闭菜单" data-mn-en="Close menu">${icons.close}</button></header><nav class="mn-links" aria-label="手机导航"><a href="./">${icons.home}<span data-mobile-text data-mn-zh="首页" data-mn-en="Home">首页</span><i>↗</i></a><button data-mn-works>${icons.works}<span data-mobile-text data-mn-zh="我的作品" data-mn-en="My designs">我的作品</span><i>↗</i></button><a href="./checkout.html?view=orders">${icons.orders}<span data-mobile-text data-mn-zh="我的订单" data-mn-en="My orders">我的订单</span><i>↗</i></a><a href="./print-locations.html">${icons.home}<span data-mobile-text data-mn-zh="打印设备" data-mn-en="Print locations">打印设备</span><i>↗</i></a><a href="./about.html">${icons.about}<span data-mobile-text data-mn-zh="关于我们" data-mn-en="About us">关于我们</span><i>↗</i></a><button data-mn-contact>${icons.contact}<span data-mobile-text data-mn-zh="联系我们" data-mn-en="Contact us">联系我们</span><i>↗</i></button></nav><footer class="mn-drawer-footer"><span class="mn-language-label" data-mobile-text data-mn-zh="语言" data-mn-en="Language">语言</span><div class="mn-language" role="group" aria-label="Language / 语言"><button data-mn-lang="zh" aria-pressed="true">中文</button><button data-mn-lang="en" aria-pressed="false">English</button></div><p>A little more you.</p></footer>`;const panel=document.createElement("div");panel.className="mn-panel";while(drawer.firstChild)panel.append(drawer.firstChild);drawer.append(panel);document.body.append(drawer);
 const shade=document.createElement('div');shade.className='mn-shade';shade.hidden=true;document.body.append(shade);let blocked=[];
 drawer.showModal=()=>{blocked=[...document.body.children].filter(el=>el!==drawer&&el!==shade).map(el=>[el,el.inert]);blocked.forEach(([el])=>el.inert=true);drawer.hidden=false;drawer.open=true;drawer.setAttribute('open','');shade.hidden=false;drawer.querySelector('.mn-close').focus({preventScroll:true});};
 drawer.close=()=>{drawer.hidden=true;drawer.open=false;drawer.removeAttribute('open');shade.hidden=true;blocked.forEach(([el,was])=>el.inert=was);blocked=[];opener.focus({preventScroll:true});};
 document.addEventListener('keydown',e=>{if(!drawer.open)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const items=[...drawer.querySelectorAll('a,button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 const opener=actions.querySelector('button');let closing=false;
 function sync(){document.querySelectorAll('[data-site-zh]').forEach(el=>{const text=el.dataset[en()?'siteEn':'siteZh'];if(el.textContent!==text)el.textContent=text;});document.querySelectorAll('[data-mobile-text]').forEach(el=>{const value=el.dataset[en()?'mnEn':'mnZh'];if(el.textContent!==value)el.textContent=value;});document.querySelectorAll('[data-mobile-label]').forEach(el=>el.setAttribute('aria-label',el.dataset[en()?'mnEn':'mnZh']));drawer.setAttribute('aria-label',t('主菜单','Main menu'));drawer.querySelector('nav').setAttribute('aria-label',t('手机导航','Mobile navigation'));drawer.querySelectorAll('[data-mn-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mnLang===(en()?'en':'zh'))));}
 function open(){if(drawer.open)return;sync();drawer.showModal();drawer.style.right='0px';drawer.scrollTop=0;opener.setAttribute('aria-expanded','true');document.documentElement.classList.add('mn-menu-open');if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const animation=panel.animate([{transform:'translateX(100%)'},{transform:'translateX(0)'}],{duration:240,easing:'ease-out'});setTimeout(()=>animation.cancel(),260);}}

 async function close(){if(!drawer.open||closing)return;closing=true;try{if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await Promise.race([drawer.animate([{transform:'translateX(0)'},{transform:'translateX(100%)'}],{duration:180,easing:'ease-in',fill:'forwards'}).finished,new Promise(resolve=>setTimeout(resolve,220))]);}finally{drawer.getAnimations().forEach(a=>a.cancel());drawer.close();closing=false;document.documentElement.classList.remove('mn-menu-open');opener.setAttribute('aria-expanded','false');}}
 opener.onclick=open;shade.onclick=close;drawer.querySelector('.mn-close').onclick=close;drawer.addEventListener('cancel',e=>{e.preventDefault();close();});drawer.addEventListener('click',e=>{if(e.target===drawer&&e.clientX<drawer.getBoundingClientRect().left)close();});drawer.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{drawer.close();document.documentElement.classList.remove('mn-menu-open');opener.setAttribute('aria-expanded','false');}));
 drawer.querySelectorAll('[data-mn-lang]').forEach(button=>button.onclick=()=>{const select=document.querySelector('#flow-language,#language-select');if(select){select.value=button.dataset.mnLang;select.dispatchEvent(new Event('change',{bubbles:true}));sync();}});
 function info(title,description,linkLabel,href){const modal=document.createElement('dialog');modal.className='mn-info';modal.setAttribute('aria-label',title);const top=document.createElement('header');const heading=document.createElement('h2');heading.textContent=title;const button=document.createElement('button');button.innerHTML=icons.close;button.setAttribute('aria-label',t('关闭','Close'));button.onclick=()=>modal.close();top.append(heading,button);const p=document.createElement('p');p.textContent=description;modal.append(top,p);if(href){const link=document.createElement('a');link.href=href;link.textContent=linkLabel+' ↗';link.className='mn-info-action';modal.append(link);}document.body.append(modal);modal.showModal();modal.addEventListener('close',()=>modal.remove(),{once:true});}
 drawer.querySelector('[data-mn-contact]').onclick=async()=>{await close();const contact=document.querySelector('#aimo-contact-dialog');if(contact)contact.showModal();else info(t('联系我们','Contact us'),t('联系信息待添加。','Contact details coming soon.'));};
 drawer.querySelector('[data-mn-works]').onclick=async()=>{await close();location.href='./my-designs.html';};
 const worksButton=document.querySelector('#draft-button');if(worksButton&&!document.body.classList.contains('home-page'))worksButton.onclick=()=>{location.href='./my-designs.html';};function syncDesignCount(){try{const designs=JSON.parse(sessionStorage.getItem('popomo-home-designs')||'[]');const count=document.querySelector('#draft-count');if(count)count.textContent=Array.isArray(designs)?designs.length:0;}catch{}}syncDesignCount();document.addEventListener('visibilitychange',syncDesignCount);const path=location.pathname;header.querySelectorAll('.site-nav>a,.orders-link').forEach(link=>{const url=new URL(link.href);if(!url.hash&&url.pathname===path)link.setAttribute('aria-current','page');});if(path.endsWith('/my-designs.html'))worksButton?.setAttribute('aria-current','page');if(path.endsWith('/account.html'))desktopAccount.setAttribute('aria-current','page');const observer=new MutationObserver(sync);observer.observe(document.documentElement,{attributes:true,attributeFilter:['lang']});matchMedia('(min-width:761px)').addEventListener('change',e=>{if(e.matches&&drawer.open)close();});sync();
}
